--
-- Table structure for table `log`
--

DROP TABLE IF EXISTS `log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `log` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ログID',
  `operate_emp_id` int DEFAULT NULL COMMENT '操作社員ID',
  `operation_time` datetime DEFAULT NULL COMMENT '操作日時',
  `class_name` varchar(255) DEFAULT NULL COMMENT '完全修飾クラス名',
  `method_name` varchar(100) DEFAULT NULL COMMENT 'メソッド名',
  `args` varchar(2000) DEFAULT NULL COMMENT 'リクエスト引数 (JSON)',
  `result` varchar(2000) DEFAULT NULL COMMENT '実行結果 (JSON)',
  `cost_time` bigint DEFAULT NULL COMMENT '処理時間 (ミリ秒)',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='操作ログテーブル';
/*!40101 SET character_set_client = @saved_cs_client */;

