--
-- Table structure for table `student`
--

DROP TABLE IF EXISTS `student`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '受講生ID',
  `name` varchar(50) DEFAULT NULL COMMENT '氏名',
  `no` char(10) DEFAULT NULL COMMENT '学籍番号',
  `gender` tinyint DEFAULT NULL COMMENT '性別 (1:男性, 2:女性)',
  `phone` varchar(20) DEFAULT NULL COMMENT '電話番号',
  `id_card` char(18) DEFAULT NULL COMMENT 'マイナンバー/身分証明書番号',
  `is_college` tinyint DEFAULT NULL COMMENT '大学の在校生ですか',
  `address` varchar(100) DEFAULT NULL COMMENT '住所',
  `degree` tinyint DEFAULT NULL COMMENT '最終学歴 (1:中学, 2:高校, 3:専門/短大, 4:大学, 5:大学院)',
  `graduation_date` date DEFAULT NULL COMMENT '卒業年月日',
  `clazz_id` int DEFAULT NULL COMMENT '所属クラスID',
  `violation_count` tinyint unsigned DEFAULT '0' COMMENT '違反回数',
  `violation_score` tinyint unsigned DEFAULT '0' COMMENT '違反点数',
  `create_time` datetime DEFAULT NULL COMMENT '作成日時',
  `update_time` datetime DEFAULT NULL COMMENT '更新日時',
  PRIMARY KEY (`id`),
  UNIQUE KEY `no` (`no`),
  UNIQUE KEY `phone` (`phone`),
  UNIQUE KEY `id_card` (`id_card`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='受講生情報テーブル';
/*!40101 SET character_set_client = @saved_cs_client */;

